jQuery(function(t){t("#ml_box").on("click",".strope-button",function(){var a=t(this).hasClass("wp-ui-text-highlight"),e=t(this).attr("id"),s=t("#htr_lang_"+e.replace("strope_sync_post[","").replace("]","")).val();if(typeof s>"u"||s==0||a||confirm(strope_sync_post.confirm_text)){var o={action:"toggle_"+e,value:a,post_type:t("#post_type").val(),_strope_nonce:t("#_strope_nonce").val()};t.post(ajaxurl,o,function(n){var p=wpAjax.parseAjaxResponse(n,"strope-ajax-response");t.each(p.responses,function(){e=e.replace("[","\\[").replace("]","\\]"),t("#"+e).toggleClass("wp-ui-text-highlight").attr("title",this.data).children("span").text(this.data),t('input[name="'+e+'"]').val(!o.value)})})}})});
